#!/usr/bin/env python3
"""Regenerate crates/ytnef-core/src/tags.rs from the C ytnef headers.

Usage: scripts/gen-tags.py <ytnef C source dir>   (e.g. target/oracle/src)
"""
import re
import sys
from pathlib import Path

src = Path(sys.argv[1]) / "lib"
defs = {}
for m in re.finditer(r"#define\s+(PR_\w+)\s+(0x[0-9A-Fa-f]+)", (src / "mapidefs.h").read_text()):
    defs.setdefault(m.group(1), int(m.group(2), 16))
names = re.findall(r"MAPIMACRO\((PR_\w+)\)", (src / "mapitags.h").read_text())

out = [
    "//! `PR_*` property names, generated by `scripts/gen-tags.py` from C",
    "//! `mapitags.h` (`MPList`) and `mapidefs.h`. Do not edit by hand.",
    "",
    "/// `(property ID, name)` in `MPList` order. IDs repeat; C prints the first.",
    "pub const TAGS: &[(u16, &str)] = &[",
]
out += [f'    (0x{defs[n]:04X}, "{n}"),' for n in names]
out += [
    "];",
    "",
    "/// Name C's `MAPIPrint` shows for a property ID.",
    "pub fn tag_name(id: u16) -> Option<&'static str> {",
    "    TAGS.iter().find(|(i, _)| *i == id).map(|(_, n)| *n)",
    "}",
    "",
]
Path(__file__).resolve().parent.parent.joinpath("crates/ytnef-core/src/tags.rs").write_text("\n".join(out))
